/**
 * RolesGuard — flat any-of role authorization check.
 *
 * Evaluates whether the authenticated principal holds at least one of the
 * roles declared by `@Roles(...)`. No transitive role hierarchy is applied;
 * roles are checked by exact name against the principal's literally-held
 * normalized roles (set by AuthGuard from the provider plan roleMappings).
 *
 * Auto-generated by datrix-codegen-typescript. Do not edit manually.
 */
import { CanActivate, ExecutionContext, Injectable, Logger } from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { ROLES_KEY } from './roles.decorator';
import type { IdentityPrincipal } from './identity';

@Injectable()
export class RolesGuard implements CanActivate {
  private readonly logger = new Logger(RolesGuard.name);

  constructor(private readonly reflector: Reflector) {}

  canActivate(context: ExecutionContext): boolean {
    const requiredRoles = this.reflector.getAllAndOverride<string[]>(ROLES_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);
    if (!requiredRoles || requiredRoles.length === 0) {
      return true;
    }

    const request = context.switchToHttp().getRequest() as Record<string, unknown>;
    const user = request['user'] as IdentityPrincipal | undefined;
    if (!user) {
      return false;
    }

    // Flat any-of: no hierarchy expansion; roles are normalized by AuthGuard.
    const principalRoles: ReadonlyArray<string> = user.roles ?? [];
    const hasRole = requiredRoles.some((role) => principalRoles.includes(role));
    if (!hasRole) {
      this.logger.warn(
        `role_check_denied required=${requiredRoles.join(',')}`,
      );
    }
    return hasRole;
  }
}
